/*
 * TREASURE HOUNDS - level data. maps.c is generated by tools/maps/make_maps.py.
 *
 * Map characters (terrain):
 *   .  floor (grass / cave / temple slab / sand, by level)   ,  second floor (dirt / mud / mossy slab / wet sand)
 *   :  cobblestone   =  planks   -  ship deck   "  rug   `  sand   '  wet sand
 *   ~  deep water    w  shallow water   (space) void   #  wall (cliff / cave / temple brick)
 *   W  wooden wall   U  ship hull   h  hedge   ^  spike trap   _  crumbling floor   p  pressure plate   G  grate
 * Objects sit on the floor of the tile to their left (or above) - see the table in world.c.
 */
#ifndef MAPS_H
#define MAPS_H

#include <stdint.h>

enum { COND_NONE, COND_PLATES, COND_BRAZIERS, COND_LEVER, COND_ORGAN, COND_GEARS, COND_KEY, COND_BOSS };

typedef struct { int8_t x0, y0, x1, y1; int16_t scene; uint8_t flags; } MapTrig;   /* tile rect, inclusive */
typedef struct { int8_t gate; uint8_t cond; int8_t x0, y0, x1, y1; } MapGroup;    /* gate index opens when cond met in rect */
typedef struct { int8_t x, y, lx, ly; } MapHook;                                  /* hook tile, landing tile */
typedef struct { int8_t x, y; int8_t dx, dy; int8_t tx0, ty0, tx1, ty1; } MapBoulder;   /* boulder start, roll dir, trigger rect */

enum { TRIG_ONCE = 1, TRIG_CHECKPOINT = 2, TRIG_EXIT = 4, TRIG_BANTER = 8 };

typedef struct {
    const char *name, *subtitle;
    int w, h, theme;
    const char *const *rows;
    const MapTrig *trig;     int ntrig;
    const MapGroup *group;   int ngroup;
    const char *const *sign; int nsign;
    const int8_t *pipe;      int npipe;   /* bone pipe notes, reading order */
    const int8_t *organ;     int norgan;  /* the tune to play */
    const MapHook *hook;     int nhook;
    const MapBoulder *boul;  int nboul;
} LevelData;

enum { THEME_TOWN, THEME_CAVE, THEME_TEMPLE, THEME_COVE };

#define NUM_LEVELS 4
extern const LevelData LEVELS[NUM_LEVELS];

#endif
